from pathlib import Path
from bs4 import BeautifulSoup
import shutil
R=Path('/workspace/work/deliverables/dockside');C=R/'collection/dockside';V=R/'review'
def grid(h):return '<div class="group" style="grid-column:1 / span 12;grid-row:1 / span 6">'+h+'</div>'
def save(n,content,headclass='head',title=None,kicker=None):
 p=V/f'reassembled/slide_{n:02}.html';b=BeautifulSoup(p.read_text(),'html.parser');b.select_one('.slide')['class']=['slide','overrides'];head=b.select_one('.head');head['class']=headclass.split()
 if title:head.select_one('.title').clear();head.select_one('.title').append(BeautifulSoup(title,'html.parser'))
 if kicker:head.select_one('.kicker').string=kicker
 body=b.select_one('.body');body.clear();body.append(BeautifulSoup(content,'html.parser'));p.write_text(str(b));return b,p
